SELECT DISTINCT
css.SUBMIT_TYPE repName, cir.UPLOAD_FILE_ID as repFileId, cir.UPDATE_TIME as repDate, (case when cir.CHECK_TOTAL_COUNT= '0' then '01' when cir.CHECK_TOTAL_COUNT = cir.CHECK_SUCCESS_COUNT then '02' when cir.CHECK_TOTAL_COUNT = cir.CHECK_FAILED_COUNT then '03' else '04' end) as repResult, cir.REPORT_NO as reportNo, cir.SUBMIT_COUNT as submitCount, cir.CHECK_TOTAL_COUNT as checkTotalCount, cir.CHECK_SUCCESS_COUNT as checkSuccessCount, cir.CHECK_FAILED_COUNT as checkFailedCount from CHB_INFO_REPORT cir LEFT JOIN CHB_SUBMIT_STATUS css ON cir.REPORT_NO = css.REPORT_NO
#{repName}
and DATE_FORMAT(css.UPDATE_TIME, '%Y-%m-%d') >= #{repDateStart}
and DATE_FORMAT(css.UPDATE_TIME, '%Y-%m-%d') <= #{repDateEnd}
order by cir.UPDATE_TIME desc

SELECT cir.SUBMIT_TYPE repName, /***三期CHB_SUBMIT_STATUS去除改造 20220310**/ cir.SUBMIT_TYPE repCode, /***三期CHB_SUBMIT_STATUS去除改造 20220310**/ cir.UPLOAD_FILE_ID as repFileId, cir.CREATE_TIME as repDate, (case when cir.CHECK_TOTAL_COUNT= '0' then '01' when cir.CHECK_TOTAL_COUNT = cir.CHECK_SUCCESS_COUNT then '02' when cir.CHECK_TOTAL_COUNT = cir.CHECK_FAILED_COUNT then '03' else '04' end) as repResult, cir.REPORT_NO as reportNo, cir.SUBMIT_COUNT as submitCount, cir.CHECK_TOTAL_COUNT as checkTotalCount, cir.CHECK_SUCCESS_COUNT as checkSuccessCount, cir.CHECK_FAILED_COUNT as checkFailedCount from CHB_INFO_REPORT cir
#{repName}
and DATE_FORMAT(cir.CREATE_TIME, '%Y-%m-%d') >= #{repDateStart}
and DATE_FORMAT(cir.CREATE_TIME, '%Y-%m-%d') <= #{repDateEnd}
order by cir.CREATE_TIME desc

SELECT /***三期CHB_SUBMIT_STATUS去除改造 20220310**/ css.SUMIT_SEQ as seqNo, null AS submitNum,
'14' as repName,
'16' as repName,
/***三期CHB_SUBMIT_STATUS去除改造 20220310**/ css.SUBMIT_FEEDBACK_STATUS repResult, css.UPDATE_TIME repDate, cir.UPLOAD_FILE_ID as repFileId, css.REPORT_NO reportNo, css.SUBMIT_FEEDBACK_MSG repFailedInfo, /***三期CHB_SUBMIT_STATUS去除改造 20220310**/
css.INDENTIFY_MARK as uniqueIdenti
css.ORG_CODE||','||css.INDENTIFY_MARK||','||css.PRD_REGIST_CODE||','||to_char(css.HOLD_DATE,'yyyy-MM-dd')||','||css.CCY as uniqueIdenti
/***三期CHB_SUBMIT_STATUS去除改造 20220310**/ FROM
/***三期CHB_SUBMIT_STATUS去除改造 20220310**/
CHB_EQU_SUB css
CHB_INVESTHOLD_INFO_SUB css
/***三期CHB_SUBMIT_STATUS去除改造 20220310**/ left join CHB_INFO_REPORT cir on css.REPORT_NO = cir.REPORT_NO where css.REPORT_NO= #{reportNo}
#{repResult}
/***三期CHB_SUBMIT_STATUS去除改造 20220310**/ and css.ORG_CODE||','||css.INDENTIFY_MARK||','||css.PRD_REGIST_CODE||','||to_char(css.HOLD_DATE,'yyyy-MM-dd')||','||css.CCY like '%' || #{uniqueIdenti} || '%' /***三期CHB_SUBMIT_STATUS去除改造 20220310**/
UNION ALL
SELECT cess.SEQNO AS seqNo, cess.SUBMIT_NUM AS submitNum, cess.SUBMIT_TYPE AS repName, cess.SUBMIT_FEEDBACK_STATUS repResult, cess.UPDATE_TIME repDate, cir.UPLOAD_FILE_ID AS repFileId, cess.REPORT_NO reportNo, cess.SUBMIT_FEEDBACK_MSG repFailedInfo, cess.UNIQUE_IDENTI uniqueIdenti FROM CHB_EQUDET_SUBMIT_STATUS cess LEFT JOIN CHB_INFO_REPORT cir ON cir.REPORT_NO = CESS.REPORT_NO WHERE cess.REPORT_NO = #{reportNo}
#{repResult}
and cess.UNIQUE_IDENTI like concat_ws('','%', #{uniqueIdenti}, '%')
